package com.northstar.crm.ui;

import com.northstar.crm.domain.*;import com.northstar.crm.security.ActorResolver;import com.northstar.crm.service.OrganizationService;import com.vaadin.flow.component.*;import com.vaadin.flow.component.button.Button;import com.vaadin.flow.component.dialog.Dialog;import com.vaadin.flow.component.formlayout.FormLayout;import com.vaadin.flow.component.grid.Grid;import com.vaadin.flow.component.html.*;import com.vaadin.flow.component.orderedlayout.*;import com.vaadin.flow.component.textfield.*;import com.vaadin.flow.component.combobox.ComboBox;import com.vaadin.flow.component.datepicker.DatePicker;import com.vaadin.flow.data.binder.*;import com.vaadin.flow.data.renderer.ComponentRenderer;import com.vaadin.flow.router.*;import jakarta.annotation.security.PermitAll;import java.time.LocalDate;import static com.northstar.crm.domain.DomainTypes.*;
@Route(value="organizations",layout=MainLayout.class) @PageTitle("Organizations · Northstar") @PermitAll public class OrganizationsView extends VerticalLayout {
 private final OrganizationService service;private final Grid<Organization> grid=new Grid<>();private final TextField search=UiKit.search("Search organizations");private final boolean canCreate;
 public OrganizationsView(OrganizationService service,ActorResolver actors){this.service=service;canCreate=actors.current().getRole()==Role.PLATFORM_ADMIN||actors.current().getRole()==Role.ACCOUNT_MANAGER;configureGrid();search.addValueChangeListener(e->refresh());var actions=new HorizontalLayout(search);if(canCreate)actions.add(UiKit.primary("New organization",e->openForm(null)));actions.setWidthFull();actions.expand(search);var panel=new VerticalLayout(actions,grid);panel.addClassName("panel");add(UiKit.page("CUSTOMER PORTFOLIO","Organizations","Every account in your authorized portfolio, with renewal and health context.",panel));setPadding(false);setSizeFull();refresh();}
 private void configureGrid(){grid.addColumn(Organization::getName).setHeader("Organization").setSortable(true).setFlexGrow(2);grid.addColumn(Organization::getPlan).setHeader("Plan");grid.addColumn(new ComponentRenderer<>(o->UiKit.badge(o.getHealth()))).setHeader("Health");grid.addColumn(o->o.getHealthScore()+" / 100").setHeader("Score");grid.addColumn(Organization::getRenewalDate).setHeader("Renews").setSortable(true);grid.addColumn(new ComponentRenderer<>(o->UiKit.badge(o.getStatus()))).setHeader("Status");grid.addItemClickListener(e->UI.getCurrent().navigate("organizations/"+e.getItem().getId()));grid.setEmptyStateText("No organizations match this search.");}
 private void refresh(){grid.setItems(service.search(search.getValue()));}
 private void openForm(Organization existing){var dialog=new Dialog();dialog.setHeaderTitle(existing==null?"Create organization":"Edit organization");var name=new TextField("Organization name");var plan=new ComboBox<String>("Plan");plan.setItems("Launch","Scale","Enterprise");var status=new ComboBox<OrganizationStatus>("Status");status.setItems(OrganizationStatus.values());var health=new ComboBox<Health>("Health");health.setItems(Health.values());var score=new IntegerField("Health score");score.setMin(0);score.setMax(100);var renewal=new DatePicker("Renewal date");var billing=new EmailField("Billing contact email");var risk=new TextArea("Risk assessment");risk.setMaxLength(500);risk.setWidthFull();var binder=new Binder<OrganizationForm>(OrganizationForm.class);binder.forField(name).asRequired("Name is required").bind(OrganizationForm::getName,OrganizationForm::setName);binder.forField(plan).asRequired().bind(OrganizationForm::getPlan,OrganizationForm::setPlan);binder.forField(status).asRequired().bind(OrganizationForm::getStatus,OrganizationForm::setStatus);binder.forField(health).asRequired().bind(OrganizationForm::getHealth,OrganizationForm::setHealth);binder.forField(score).asRequired().withValidator(v->v>=0&&v<=100,"Use 0–100").bind(OrganizationForm::getScore,OrganizationForm::setScore);binder.forField(renewal).asRequired().bind(OrganizationForm::getRenewal,OrganizationForm::setRenewal);binder.forField(billing).asRequired().bind(OrganizationForm::getBilling,OrganizationForm::setBilling);binder.forField(risk).bind(OrganizationForm::getRisk,OrganizationForm::setRisk);var bean=existing==null?new OrganizationForm():OrganizationForm.from(existing);binder.setBean(bean);var form=new FormLayout(name,plan,status,health,score,renewal,billing,risk);form.setResponsiveSteps(new FormLayout.ResponsiveStep("0",1),new FormLayout.ResponsiveStep("540px",2));form.setColspan(risk,2);dialog.add(form);dialog.getFooter().add(new Button("Cancel",e->dialog.close()),UiKit.primary("Save organization",e->{try{if(!binder.validate().isOk())return;var i=new OrganizationService.OrganizationInput(bean.name,bean.plan,bean.status,bean.health,bean.score,bean.renewal,bean.billing,bean.risk);if(existing==null)service.create(i);else service.update(existing.getId(),i);dialog.close();refresh();UiKit.success("Organization saved");}catch(Exception ex){UiKit.error(ex);}}));dialog.setWidth("min(760px, 94vw)");dialog.open();}
 public static class OrganizationForm {private String name="";private String plan="Scale";private OrganizationStatus status=OrganizationStatus.ONBOARDING;private Health health=Health.GOOD;private Integer score=70;private LocalDate renewal=LocalDate.now().plusMonths(12);private String billing="";private String risk="";static OrganizationForm from(Organization o){var f=new OrganizationForm();f.name=o.getName();f.plan=o.getPlan();f.status=o.getStatus();f.health=o.getHealth();f.score=o.getHealthScore();f.renewal=o.getRenewalDate();f.billing=o.getBillingEmail();f.risk=o.getRiskSummary();return f;}public String getName(){return name;}public void setName(String v){name=v;}public String getPlan(){return plan;}public void setPlan(String v){plan=v;}public OrganizationStatus getStatus(){return status;}public void setStatus(OrganizationStatus v){status=v;}public Health getHealth(){return health;}public void setHealth(Health v){health=v;}public Integer getScore(){return score;}public void setScore(Integer v){score=v;}public LocalDate getRenewal(){return renewal;}public void setRenewal(LocalDate v){renewal=v;}public String getBilling(){return billing;}public void setBilling(String v){billing=v;}public String getRisk(){return risk;}public void setRisk(String v){risk=v;}}
}
